using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ENC.Respuestas;using GraphApi.Services.ENC.Respuestas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ENC.Respuestas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Respuestas: creación, actualización y eliminación.")]    public class RespuestasMutation    {        [Authorize]        [GraphQLName("createRespuestas")]        [GraphQLDescription("Crea un nuevo Respuesta usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadRespuestas> CreateRespuestasAsync(            [GraphQLDescription("Datos necesarios para crear el Respuesta.")]            clCreateRespuestas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Respuesta.")]            IRespuestasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateRespuestas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateRespuestas")]        [GraphQLDescription("Actualiza los campos especificados de un Respuesta existente.")]        public async Task<clReadRespuestas?> UpdateRespuestasAsync(            [GraphQLDescription("Datos del Respuesta a actualizar.")]            clUpdateRespuestas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Respuesta.")]            IRespuestasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateRespuestas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteRespuestas")]        [GraphQLDescription("Elimina un Respuesta por su ID.")]        public async Task<bool> delRespuestasAsync(            [GraphQLDescription("ID del Respuesta a eliminar.")]            int nRespuestasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Respuesta.")]            IRespuestasService objService        )        {            return await objService.DeleteRespuestas(nRespuestasID);        }    }}